WHERE NOT EXISTS (SELECT 1 FROM public.fact_verifications v WHERE v.entity_type='fact' AND v.entity_id=(SELECT id FROM public.gk_facts WHERE canonical_hash='b5fae06b6ab983b49cd6b3eab7ee01a0ad06c7d26f73ff34444f3ab66a50acc3' LIMIT 1) AND v.claim_text='The Geneva Conventions are four treaties adopted in 1949; the International Committee of the Red Cross lists three Additional Protocols adopted in 1977, 1977, and 2005.');
